import{_ as i,l as o,o as e,c as n,v as l,p as s,x as t,d,i as h,S as m}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"LLM 裁判偏差","description":"","frontmatter":{"title":"LLM 裁判偏差","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/llm-judge-bias.md","filePath":"llm/llm-judge-bias.md","lastUpdated":1789023840000}'),p={name:"llm/llm-judge-bias.md"};function c(_,a,E,u,A,B){const r=o("Mermaid");return e(),n("div",null,[a[1]||(a[1]=l('<h1 id="llm-裁判偏差" tabindex="-1">LLM 裁判偏差 <a class="header-anchor" href="#llm-裁判偏差" aria-label="Permalink to &quot;LLM 裁判偏差&quot;">​</a></h1><div class="epigraph"><p>用强模型给弱模型打分，便宜、可复现，也继承位置、长度与自我偏好。未经人校准的法官不是金标。</p><footer>—— Zheng 等, Judging LLM-as-a-Judge with MT-Bench and Chatbot Arena</footer></div><p><a href="/llm/model-cards">上一课</a>把开放生成的分数留给「谁来判」。本单元从 LLM 裁判开始。主干已有<a href="/llm/llm-judge-reward">裁判作奖励</a>与<a href="/llm/human-vs-auto-eval">人机评测分工</a>；本课补评测进阶里的偏差清单，不把法官再介绍一遍。缺口是：榜上的胜率常常是偏差的函数。后课成对对逐点默认偏差先被当成系统误差。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Zheng 等人在 MT-Bench 上量过：同一对回复，先呈现的更容易赢（位置偏差）；更长的更容易赢；法官偏爱同族模型的文风（自我增强）。这些偏差在 AlpacaEval、自动 Arena 里同样出现。开发期用法官当烟雾合法；论文主表用未交换顺序、未控制长度的法官分，则是测量失效。</p><p>法官还有任务失效：有标准答案的数学与代码，应用程序判，不应用法官「看起来对」。难题上法官自己会幻觉，方差大于被评模型的差。</p><p><span class="marginnote">裁判提示里写「忽略长度」几乎无效。要用交换位置、长度归一或风格控制（后课），不能靠自然语言禁令。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>成对评测：每个样本交换 \\(y_a,y_b\\) 跑两次，不一致则平局。报告与人评的一致率、Cohen \\(\\kappa\\) 或胜负相关，而不是只报法官 Elo。点分 Likert 更便宜、校准更差，只适合粗过滤。法官模型版本与温度写入协议，与 harness 哈希同等重要。</p>',9)),(e(),s(m,null,{default:t(()=>[h(r,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20PAIR%5B%22%E5%9B%9E%E5%A4%8D%E5%AF%B9%22%5D%20--%3E%20J%5B%22%E6%B3%95%E5%AE%98%E6%8F%90%E7%A4%BA%22%5D%0A%20%20J%20--%3E%20SWAP%5B%22%E6%8D%A2%E5%BA%8F%22%5D%0A%20%20SWAP%20--%3E%20AGR%5B%22%E4%B8%80%E8%87%B4%E5%88%99%E8%AE%B0%E8%83%9C%22%5D%0A%20%20J%20--%3E%20BIAS%5B%22%E4%BD%8D%E7%BD%AE%20%2F%20%E9%95%BF%E5%BA%A6%20%2F%20%E6%97%8F%E8%B0%B1%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=l('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>法官是另一个语言模型，先验来自「什么样的回答像好助手」：列表、礼貌、自信、英语流利。位置偏差来自条件顺序改变注意力与「先完整后挑剔」的叙事习惯。自我偏好来自风格重叠：同族解码器的 n-gram 与结构更像法官的预训练。偏差进入名次后，策略会向法官审美拟合，看起来像产品进步。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给「如何骗过法官」的提示。下一课把成对与逐点当作两种仪器，而不是两种文风。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LLM 法官必须换序、对人校准；未校准者不能当主表。</li><li>位置、长度、同族偏好是一等系统误差。</li><li>可程序判定的任务不要用法官。</li><li>出处：Zheng 等 MT-Bench / LLM-as-a-Judge。</li></ul>',6))])}const g=i(p,[["render",c]]);export{b as __pageData,g as default};
